<?php
$uid=$_SESSION['user']['id'];$st=$pdo->prepare("SELECT * FROM cash_sessions WHERE user_id=? AND status='open' ORDER BY id DESC LIMIT 1");$st->execute([$uid]);$open=$st->fetch();
if($_SERVER['REQUEST_METHOD']==='POST'){checkCsrf();$a=$_POST['action']??'';
 if($a==='open'&&!$open){$pdo->prepare('INSERT INTO cash_sessions(user_id,opening_amount,opened_at,status) VALUES(?,?,NOW(),"open")')->execute([$uid,(float)$_POST['opening_amount']]);audit($pdo,'open','cash',$pdo->lastInsertId(),'Caixa aberto');flash('success','Caixa aberto com sucesso.');redirect('index.php?page=cash');}
 if($a==='movement'&&$open){$type=in_array($_POST['type'],['income','expense'])?$_POST['type']:'income';$pdo->prepare('INSERT INTO cash_movements(cash_session_id,user_id,type,amount,description) VALUES(?,?,?,?,?)')->execute([$open['id'],$uid,$type,(float)$_POST['amount'],trim($_POST['description'])]);audit($pdo,'movement','cash',$open['id'],$type.' '.money((float)$_POST['amount']).' - '.trim($_POST['description']));flash('success','Movimentação registrada.');redirect('index.php?page=cash');}
 if($a==='close'&&$open){$sales=$pdo->prepare("SELECT COALESCE(SUM(sp.amount),0) FROM sale_payments sp JOIN sales s ON s.id=sp.sale_id WHERE s.cash_session_id=? AND sp.method='cash' AND s.status IN ('completed','partially_returned')");$sales->execute([$open['id']]);$salesTotal=$sales->fetchColumn();$mov=$pdo->prepare("SELECT COALESCE(SUM(CASE WHEN type='income' THEN amount ELSE -amount END),0) FROM cash_movements WHERE cash_session_id=?");$mov->execute([$open['id']]);$movTotal=$mov->fetchColumn();$expected=$open['opening_amount']+$salesTotal+$movTotal;$counted=(float)$_POST['closing_amount'];$pdo->prepare('UPDATE cash_sessions SET closing_amount=?,expected_amount=?,difference_amount=?,closed_at=NOW(),status="closed" WHERE id=?')->execute([$counted,$expected,$counted-$expected,$open['id']]);audit($pdo,'close','cash',$open['id'],'Diferença '.money($counted-$expected));flash('success','Caixa fechado. Diferença: '.money($counted-$expected));redirect('index.php?page=cash');}
}
$paymentSummary=[];$history=$pdo->prepare('SELECT * FROM cash_sessions WHERE user_id=? ORDER BY id DESC LIMIT 15');$history->execute([$uid]);$history=$history->fetchAll();$salesTotal=0;$movements=[];$expected=0;if($open){$s=$pdo->prepare("SELECT COALESCE(SUM(sp.amount),0) FROM sale_payments sp JOIN sales s ON s.id=sp.sale_id WHERE s.cash_session_id=? AND sp.method='cash' AND s.status IN ('completed','partially_returned')");$s->execute([$open['id']]);$salesTotal=$s->fetchColumn();$m=$pdo->prepare('SELECT * FROM cash_movements WHERE cash_session_id=? ORDER BY id DESC');$m->execute([$open['id']]);$movements=$m->fetchAll();$net=0;foreach($movements as $x)$net+=($x['type']==='income'?1:-1)*$x['amount'];$expected=$open['opening_amount']+$salesTotal+$net;$ps=$pdo->prepare("SELECT sp.method,SUM(sp.amount) total FROM sale_payments sp JOIN sales s ON s.id=sp.sale_id WHERE s.cash_session_id=? AND s.status IN ('completed','partially_returned') GROUP BY sp.method ORDER BY total DESC");$ps->execute([$open['id']]);$paymentSummary=$ps->fetchAll();}$title='Caixa';require __DIR__.'/../../includes/header.php';?>
<div class="page-head"><div><h1>Controle de Caixa</h1><p>Abertura, sangria, suprimento e fechamento.</p></div><span class="badge <?=$open?'ok':'danger'?>"><?=$open?'ABERTO':'FECHADO'?></span></div><?php if(!$open):?><section class="panel narrow"><h2>Abrir caixa</h2><form method="post" class="stack"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="open"><label>Fundo de caixa<input name="opening_amount" type="number" step="0.01" value="0" required></label><button class="btn primary">Abrir caixa</button></form></section><?php else:?><div class="cards"><div class="stat"><small>Abertura</small><strong><?=money($open['opening_amount'])?></strong></div><div class="stat"><small>Vendas</small><strong><?=money($salesTotal)?></strong></div><div class="stat"><small>Saldo esperado</small><strong><?=money($expected)?></strong></div></div><div class="grid two"><section class="panel"><h2>Movimentação manual</h2><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="movement"><label>Tipo<select name="type"><option value="income">Suprimento / entrada</option><option value="expense">Sangria / saída</option></select></label><label>Valor<input name="amount" type="number" step="0.01" required></label><label class="span2">Descrição<input name="description" required></label><button class="btn">Registrar</button></form><?php foreach($movements as $m):?><div class="movement"><span><?=e($m['description'])?></span><strong><?=$m['type']==='income'?'+':'-'?> <?=money($m['amount'])?></strong></div><?php endforeach;?></section><section class="panel"><h2>Resumo por pagamento</h2><?php foreach($paymentSummary as $ps):?><div class="movement"><span><?=e(paymentLabel($ps['method']))?></span><strong><?=money($ps['total'])?></strong></div><?php endforeach;?><hr><small>Somente o dinheiro compõe o saldo físico esperado da gaveta.</small></section><section class="panel"><h2>Fechar caixa</h2><form method="post" class="stack"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="close"><label>Valor contado no caixa<input name="closing_amount" type="number" step="0.01" value="<?=e($expected)?>" required></label><button class="btn danger-btn">Fechar caixa</button></form></section></div><?php endif;?><section class="panel"><h2>Últimos caixas</h2><div class="table-wrap"><table><thead><tr><th>#</th><th>Abertura</th><th>Fechamento</th><th>Esperado</th><th>Diferença</th><th>Status</th></tr></thead><tbody><?php foreach($history as $h):?><tr><td>#<?=$h['id']?></td><td><?=money($h['opening_amount'])?></td><td><?=money($h['closing_amount']??0)?></td><td><?=money($h['expected_amount']??0)?></td><td><?=money($h['difference_amount']??0)?></td><td><?=e($h['status'])?></td></tr><?php endforeach;?></tbody></table></div></section><?php require __DIR__.'/../../includes/footer.php';?>
